package com.clinic.service;
import com.clinic.config.Database;import com.clinic.util.Sql;import com.clinic.filter.SecurityFilter;import com.clinic.exception.AppException;import org.mindrot.jbcrypt.BCrypt;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.*;
public final class PasswordResetService {
 public Map<String,Object> issue(long actor,String role,long userId)throws Exception{PortalService.admin(role);String token=SecurityFilter.token();try(var c=Database.getConnection()){c.setAutoCommit(false);try{var u=Sql.one(c,"SELECT user_id,role FROM users WHERE user_id=? FOR UPDATE",userId);if(u==null||"ADMIN".equals(u.get("role")))throw new AppException(400,"Reset is available for patient and doctor accounts only.");Sql.update(c,"UPDATE password_resets SET used=TRUE WHERE user_id=?",userId);LocalDateTime expires=LocalDateTime.now().plusMinutes(30);Sql.insert(c,"INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,?)",userId,hash(token),expires);Sql.audit(c,actor,"RESET_LINK_CREATED","USER",userId);c.commit();return Map.of("resetUrl",Database.value("APP_BASE_URL","http://localhost:8080/clinic-manager")+"/reset?token="+token,"expiresAt",expires.toString());}catch(Exception e){c.rollback();throw e;}}}
 public void reset(String token,String password)throws Exception{AuthService.validatePassword(password);if(token==null||!token.matches("[A-Za-z0-9_-]{43}"))throw new AppException(400,"This reset link is invalid.");String passwordHash=BCrypt.hashpw(password,BCrypt.gensalt(12));try(var c=Database.getConnection()){c.setAutoCommit(false);try{var row=Sql.one(c,"SELECT reset_id AS id,user_id AS userId FROM password_resets WHERE token_hash=? AND used=FALSE AND expires_at>CURRENT_TIMESTAMP FOR UPDATE",hash(token));if(row==null)throw new AppException(400,"This reset link expired or has already been used.");long id=((Number)row.get("userId")).longValue();Sql.update(c,"UPDATE users SET password_hash=?,auth_version=auth_version+1 WHERE user_id=?",passwordHash,id);Sql.update(c,"UPDATE password_resets SET used=TRUE WHERE reset_id=?",row.get("id"));Sql.audit(c,id,"PASSWORD_RESET","USER",id);c.commit();}catch(Exception e){c.rollback();throw e;}}}
 private static String hash(String token)throws NoSuchAlgorithmException{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}
}
